import{_ as o,a0 as s,w as l,s as d,ao as x,I as i,x as e,a1 as t,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"2013：Linux的黃金之年-十大傑出成就 | LCTT x X-CMD","titleTemplate":false,"description":"2013：Linux的黃金之年-十大傑出成就 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"2013：Linux的黃金之年-十大傑出成就 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2013：Linux的黃金之年-十大傑出成就 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/2013：The Golden Year for Linux – 10 Biggest Linux Achievements","title":"2013：Linux的黃金之年-十大傑出成就","tag":"201401","desc":""},"relativePath":"201401/2013：The Golden Year for Linux – 10 Biggest Linux Achievements.md","filePath":"[post].md"}'),h={name:"201401/2013：The Golden Year for Linux – 10 Biggest Linux Achievements.md"};function p(u,n,g,m,L,f){const a=s("Link");return l(),d("div",null,[n[11]||(n[11]=x('<h1 id="_2013-linux的黃金之年-十大傑出成就" tabindex="-1">2013：Linux的黃金之年-十大傑出成就 <a class="header-anchor" href="#_2013-linux的黃金之年-十大傑出成就" aria-label="Permalink to “2013：Linux的黃金之年-十大傑出成就”">​</a></h1><p><strong>2013年</strong>已經過去。這一年見證了許多里程碑事件，使得2013年可以稱得上是一個<strong>Linux的黃金之年</strong>。其中一些成果在<strong>FOSS</strong>和<strong>Linux</strong>世界更可以稱得上是舉世矚目的成就。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2013/12/Year-2013-Linux.jpg" alt="2013 Year of Linux"></p><h3 id="_1-android的上升趨勢" tabindex="-1">1.Android的上升趨勢 <a class="header-anchor" href="#_1-android的上升趨勢" aria-label="Permalink to “1.Android的上升趨勢”">​</a></h3><p>2013年，Android手機達到了每日<strong>150萬</strong>的激活量記錄。不用説，正是Android的<strong>Linux內核</strong>以及它在該方面的狂熱貢獻使其達到了今天的標杆地位，這一趨勢還將在未來的日子裏一直持續下去。</p><h3 id="_2-raspberry-pi-樹莓派" tabindex="-1">2. Raspberry pi 樹莓派 <a class="header-anchor" href="#_2-raspberry-pi-樹莓派" aria-label="Permalink to “2. Raspberry pi 樹莓派”">​</a></h3><p><strong>Raspberry pi</strong>，低成本單片計算機歷史上的最偉大發明之一。它在學校和其他很多地方極大地推廣了Linux，同時在FOSS社區中也有很高的歡迎程度，這一狀況也仍將繼續。</p><h3 id="_3-debian上太空" tabindex="-1">3. Debian上太空 <a class="header-anchor" href="#_3-debian上太空" aria-label="Permalink to “3. Debian上太空”">​</a></h3><p>Debian，眾多優秀Linux發行版中的其中一款高端發行版。2013年三月下旬的一次<strong>航天飛機</strong>任務中就使用了Debian負責實驗的控制。實驗的主要內容是嘗試無土植物栽培的新方法，從而為宇航員提供空氣和食物。</p><h3 id="_4-steamos的崛起" tabindex="-1">4. SteamOS的崛起 <a class="header-anchor" href="#_4-steamos的崛起" aria-label="Permalink to “4. SteamOS的崛起”">​</a></h3><p>SteamOS，基於Debian發行版，用於<strong>Stream Machine Game Console遊戲終端</strong>，已經於<strong>2013年12月</strong>中旬發佈。GNU/Linux開始涉足於遊戲環境，這對廣大宅男極客來説當然是喜聞樂見喜大普奔。</p><h3 id="_5-linux的平板應用" tabindex="-1">5. Linux的平板應用 <a class="header-anchor" href="#_5-linux的平板應用" aria-label="Permalink to “5. Linux的平板應用”">​</a></h3><p>查看<strong>亞馬遜</strong>的平板銷量，排名前十的平板都是Android操作系統。蘋果和微軟的平板則排在第11和12位，遠遠地被拋在後面，這對於FOSS社區來説確實是一個振奮人心的消息。</p><h3 id="_6-chromebooks" tabindex="-1">6. Chromebooks <a class="header-anchor" href="#_6-chromebooks" aria-label="Permalink to “6. Chromebooks”">​</a></h3><p>Chromebooks之所以能在筆記本電腦市場贏得一席之地，是由於比起微軟等專屬平台，諸如三星，華碩等許多高端製造商給了GNU/Linux類操作系統更多的空間。</p><h3 id="_7-the-firefox-os-火狐操作系統" tabindex="-1">7. The Firefox OS 火狐操作系統 <a class="header-anchor" href="#_7-the-firefox-os-火狐操作系統" aria-label="Permalink to “7. The Firefox OS 火狐操作系統”">​</a></h3><p>Firefox OS是基於Linux和FOSS的開源操作系統，主要用於智能手機和平板，發佈於<strong>2013年4月</strong>下旬。基於<strong>ARM</strong>構架的移動設備Linux發行版顯示出了廣闊的前景。</p><h3 id="_8-kali發佈" tabindex="-1">8. Kali發佈 <a class="header-anchor" href="#_8-kali發佈" aria-label="Permalink to “8. Kali發佈”">​</a></h3><p>來自BackTrack Linux的開發者發佈了<strong>Kali Linux</strong>。Kali是是基於Debian的Linux發行版，其母系統或者説其前身(BT Linux)，主要用於滲透測試，並分享了大量的Debian版本庫，成為了最為豐富的一個發行版。Kail仍保持着在剛發佈後的很短時間內超高下載量的記錄。</p><h3 id="_9-android-kitkat" tabindex="-1">9. Android Kitkat <a class="header-anchor" href="#_9-android-kitkat" aria-label="Permalink to “9. Android Kitkat”">​</a></h3><p>儘管之前預測的發佈版本是<strong>5.0 Key Lime Pie</strong>，經過萬眾期待後，最新發布的android版本被命名為<strong>Kitkat</strong>，Google宣佈<strong>Android 4.4</strong>又名<strong>KitKat 4於2013年9月發佈</strong>。Kitkat進行了優化更新，能在具有最小的<strong>512 MB內存</strong>的設備上運行，這樣就能夠支持眾多各種各樣的設備。</p><h3 id="_10-linux-在汽車上的應用" tabindex="-1">10. Linux 在汽車上的應用 <a class="header-anchor" href="#_10-linux-在汽車上的應用" aria-label="Permalink to “10. Linux 在汽車上的應用”">​</a></h3><p>截至目前，Linux被應用於各種設備，從腕錶到遙控器，再到太空飛船，所以<strong>Linux在汽車上的應用</strong>並不讓人意外。但當Linux的作用表現在<strong>汽車趨勢雜誌</strong>的年度車上時仍然令人驚訝。2013年被選為優勝候選的兩個車型，都運行Linux系統。</p><p>2013年已經過去，但故事遠沒有結束，我們可能錯過了一些重要的里程碑，你可以在評論部分告訴我們。2014年，未來，還在繼續……</p><hr>',25)),i("p",null,[n[1]||(n[1]=e("via: ",-1)),t(a,{href:"http://www.tecmint.com/2013-the-golden-year-for-linux-and-foss/"},{default:r(()=>[...n[0]||(n[0]=[e("http://www.tecmint.com/2013-the-golden-year-for-linux-and-foss/",-1)])]),_:1})]),i("p",null,[n[4]||(n[4]=e("譯者：",-1)),t(a,{href:"https://github.com/yechunxiao19"},{default:r(()=>[...n[2]||(n[2]=[e("烏龍茶",-1)])]),_:1}),n[5]||(n[5]=e(" 校對：",-1)),t(a,{href:"http://blog.csdn.net/tinyeyeser"},{default:r(()=>[...n[3]||(n[3]=[e("Mr小眼兒",-1)])]),_:1})]),i("p",null,[n[8]||(n[8]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...n[6]||(n[6]=[e("LCTT",-1)])]),_:1}),n[9]||(n[9]=e(" 原創翻譯，",-1)),t(a,{href:"http://linux.cn/"},{default:r(()=>[...n[7]||(n[7]=[e("Linux中國",-1)])]),_:1}),n[10]||(n[10]=e(" 榮譽推出",-1))])])}const T=o(h,[["render",p]]);export{k as __pageData,T as default};
